// Auto-generated SPI Register Interface
// Generated by spireg.py from registers.csv (sha256 362925a3678f699c...)
// Verilog-2005 compatible, synthesizable (single clock + single async per block)
//
// Protocol: Variable-length transfers
//   Byte 0 : 1 RW bit + 7-bit address
//   Byte 1+: 8-bit data (address auto-increments after each byte)
//   Burst length unbounded; past the last register writes are dropped and
//   reads return 0x00 (addr_sat)
// Mode 0: CPOL=0, CPHA=0
//
// Reset / CS strategy:
//   rst_n    : async system reset, resets everything
//   armed    : set by cs_n falling, cleared by rst_n; a frame interrupted
//              by rst_n is ignored until cs_n deasserts and reasserts
//   spi_arst : combined async reset (cs_n | ~rst_n | ~armed), used by
//              receive and TX blocks as a single async-reset edge
//   CS framing is mandatory (cs_n tied low is not supported)
//   cs_n     : Write block uses cs_n as level gate only (not in sensitivity list)
//
// MISO: core drives MISO at all times; pad-ring should tri-state when cs_n=1
`timescale 1ns / 1ps

module spi_reg_interface (
    // SPI interface
    input  wire       sclk,
    input  wire       mosi,
    output reg        miso,
    input  wire       cs_n,

    // System reset (active low, async)
    input  wire       rst_n,

    // Read-only field inputs (from chip internals)
    input  wire       STATUS_ready_i,
    input  wire       STATUS_error_i,
    input  wire       STATUS_busy_i,
    input  wire [4:0] STATUS_reserved_i,
    input  wire [7:0] DATA_OUT_data_i,
    input  wire [7:0] ID_chip_id_i,
    input  wire [3:0] MIXED_ro_hi_i,

    // Read-write field outputs (to chip internals)
    output wire       CONTROL_enable_o,
    output wire [1:0] CONTROL_mode_o,
    output wire [4:0] CONTROL_reserved_o,
    output wire [7:0] DATA_IN_data_o,
    output wire [3:0] CONFIG_threshold_o,
    output wire [2:0] CONFIG_gain_o,
    output wire       CONFIG_invert_o,
    output wire [3:0] MIXED_rw_lo_o
);


    //====================================================================
    // Internal Declarations
    //====================================================================

    // SPI framing state
    reg [6:0]           rx_shift;   // MOSI history; rx_next = {rx_shift, mosi}
    reg [2:0]           bit_idx;    // free-running bit index within the byte
    reg                 cmd_done;   // set at the end of byte 0 (addr captured)
    reg                 rw_bit;     // captured R/W bit from byte 0
    reg [6:0]           addr;       // captured 7-bit register address
    reg                 addr_sat;   // increment ran past the last register

    // TX path
    reg [7:0]           tx_shift;
    reg                 tx_active;

    // Combinational read data (registered name kept for clarity)
    reg [7:0]           read_byte;  // driven by always@*, not a flop

    wire [7:0] rx_next = {rx_shift, mosi};

    // Frame arming: set by the cs_n falling edge that starts a frame,
    // cleared by rst_n. If rst_n is asserted while cs_n is low, the rest
    // of that frame stays in reset instead of being re-parsed from an
    // arbitrary bit as a new command. cs_n is a clock for this one flop.
    reg                 armed;

    always @(negedge cs_n or negedge rst_n) begin
        if (!rst_n) armed <= 1'b0;
        else        armed <= 1'b1;
    end

    // Combined async reset: cs_n deasserted, system reset, or frame not
    // armed (true 2-edge FF). Deasserts glitch-free at a cs_n falling
    // edge: cs_n drops first, ~armed follows one clock-to-q later.
    wire spi_arst = cs_n | ~rst_n | ~armed;

    // RW field storage (each reg is exactly the field width;
    // RO bits of a mixed register have no storage at all)
    reg CONTROL_enable_reg;
    reg [1:0] CONTROL_mode_reg;
    reg [4:0] CONTROL_reserved_reg;
    reg [7:0] DATA_IN_data_reg;
    reg [3:0] CONFIG_threshold_reg;
    reg [2:0] CONFIG_gain_reg;
    reg CONFIG_invert_reg;
    reg [3:0] MIXED_rw_lo_reg;

    //====================================================================
    // 2-FF Synchronizers for RO inputs
    // Clock: SCLK. Both stages sit in the same posedge block, so the
    // first stage has one full SCLK period (minus the second flop's
    // setup time) to settle. Evaluate MTBF at the maximum rated SCLK.
    //
    // These synchronize each bit independently and do NOT guarantee
    // coherency across a multi-bit RO field: bits may resolve
    // differently and a read can return a value that never existed in
    // the source domain. Multi-bit RO inputs must be held stable for
    // the duration of a transaction; holding them stable between
    // transactions satisfies this trivially.
    //====================================================================

    reg STATUS_ready_sync1, STATUS_ready_sync2;
    reg STATUS_error_sync1, STATUS_error_sync2;
    reg STATUS_busy_sync1, STATUS_busy_sync2;
    reg [4:0] STATUS_reserved_sync1, STATUS_reserved_sync2;
    reg [7:0] DATA_OUT_data_sync1, DATA_OUT_data_sync2;
    reg [7:0] ID_chip_id_sync1, ID_chip_id_sync2;
    reg [3:0] MIXED_ro_hi_sync1, MIXED_ro_hi_sync2;

    always @(posedge sclk or negedge rst_n) begin
        if (!rst_n) begin
            STATUS_ready_sync1 <= 1'b0;
            STATUS_ready_sync2 <= 1'b0;
            STATUS_error_sync1 <= 1'b0;
            STATUS_error_sync2 <= 1'b0;
            STATUS_busy_sync1 <= 1'b0;
            STATUS_busy_sync2 <= 1'b0;
            STATUS_reserved_sync1 <= 5'd0;
            STATUS_reserved_sync2 <= 5'd0;
            DATA_OUT_data_sync1 <= 8'd0;
            DATA_OUT_data_sync2 <= 8'd0;
            ID_chip_id_sync1 <= 8'd0;
            ID_chip_id_sync2 <= 8'd0;
            MIXED_ro_hi_sync1 <= 4'd0;
            MIXED_ro_hi_sync2 <= 4'd0;
        end
        else begin
            STATUS_ready_sync1 <= STATUS_ready_i;
            STATUS_ready_sync2 <= STATUS_ready_sync1;
            STATUS_error_sync1 <= STATUS_error_i;
            STATUS_error_sync2 <= STATUS_error_sync1;
            STATUS_busy_sync1 <= STATUS_busy_i;
            STATUS_busy_sync2 <= STATUS_busy_sync1;
            STATUS_reserved_sync1 <= STATUS_reserved_i;
            STATUS_reserved_sync2 <= STATUS_reserved_sync1;
            DATA_OUT_data_sync1 <= DATA_OUT_data_i;
            DATA_OUT_data_sync2 <= DATA_OUT_data_sync1;
            ID_chip_id_sync1 <= ID_chip_id_i;
            ID_chip_id_sync2 <= ID_chip_id_sync1;
            MIXED_ro_hi_sync1 <= MIXED_ro_hi_i;
            MIXED_ro_hi_sync2 <= MIXED_ro_hi_sync1;
        end
    end

    //====================================================================
    // Combinational Read Mux
    // read_byte is valid one combinational delay after addr is updated.
    // TX block samples it on the negedge that starts each data byte,
    // giving one full SCLK half-period for addr -> read_byte to settle.
    // Gated by addr_sat so a burst that runs past the last register reads
    // back 0x00 rather than repeating the last register's contents.
    //====================================================================

    always @* begin
        read_byte = 8'h00;
        if (!addr_sat) begin
            case (addr)
                7'h00: read_byte = {
                    CONTROL_reserved_reg[4:0],
                    CONTROL_mode_reg[1:0],
                    CONTROL_enable_reg
                };
                7'h01: read_byte = {
                    STATUS_reserved_sync2[4:0],
                    STATUS_busy_sync2,
                    STATUS_error_sync2,
                    STATUS_ready_sync2
                };
                7'h02: read_byte = {DATA_IN_data_reg[7:0]};
                7'h03: read_byte = {DATA_OUT_data_sync2[7:0]};
                7'h04: read_byte = {
                    CONFIG_invert_reg,
                    CONFIG_gain_reg[2:0],
                    CONFIG_threshold_reg[3:0]
                };
                7'h05: read_byte = {ID_chip_id_sync2[7:0]};
                7'h06: read_byte = {
                    MIXED_ro_hi_sync2[3:0],
                    MIXED_rw_lo_reg[3:0]
                };
                default: read_byte = 8'h00;
            endcase
        end
    end

    //====================================================================
    // SPI Receive Block (Mode 0: sample MOSI on rising SCLK)
    // Async reset: spi_arst (cs_n | ~rst_n) - true 2-edge FF.
    //====================================================================

    always @(posedge sclk or posedge spi_arst) begin
        if (spi_arst) begin
            rx_shift <= 7'd0;
            bit_idx  <= 3'd0;
            cmd_done <= 1'b0;
            rw_bit   <= 1'b0;
            addr     <= 7'd0;
            addr_sat <= 1'b0;
        end
        else begin
            // First bit of byte 0 is the R/W bit
            if (!cmd_done && bit_idx == 3'd0)
                rw_bit <= mosi;

            if (bit_idx == 3'd7) begin
                cmd_done <= 1'b1;
                if (!cmd_done)
                    addr <= rx_next[6:0];     // end of command byte
                else if (addr >= 7'h06)
                    addr_sat <= 1'b1;          // at or past the last register;
                                               // >= (not ==) so a burst starting
                                               // above the map cannot step over
                                               // the check and wrap to 0x00
                else
                    addr <= addr + 7'd1;
            end

            rx_shift <= rx_next[6:0];
            bit_idx  <= bit_idx + 3'd1;
        end
    end

    //====================================================================
    // Register Write Block
    // Sensitivity: posedge sclk + negedge rst_n only (synthesizable 2-edge FF).
    // CS gated by level: writes only occur while cs_n is asserted.
    // Write commits at every data byte boundary (bit_idx==7, cmd_done set).
    // addr_sat blocks commits once the address has run past the last register,
    // so an overlong burst is discarded instead of repeatedly hitting the top.
    // RO bits of a mixed register have no storage, so no write masking needed.
    //====================================================================

    always @(posedge sclk or negedge rst_n) begin
        if (!rst_n) begin
            CONTROL_enable_reg   <= 1'b0;
            CONTROL_mode_reg     <= 2'h0;
            CONTROL_reserved_reg <= 5'h00;
            DATA_IN_data_reg     <= 8'h00;
            CONFIG_threshold_reg <= 4'h5;
            CONFIG_gain_reg      <= 3'h3;
            CONFIG_invert_reg    <= 1'b0;
            MIXED_rw_lo_reg      <= 4'h3;
        end
        else if (!cs_n) begin
            if (rw_bit && cmd_done && bit_idx == 3'd7 && !addr_sat) begin
                case (addr)
                    7'h00: begin
                        CONTROL_enable_reg   <= rx_next[0];
                        CONTROL_mode_reg     <= rx_next[2:1];
                        CONTROL_reserved_reg <= rx_next[7:3];
                    end
                    7'h02: DATA_IN_data_reg <= rx_next[7:0];
                    7'h04: begin
                        CONFIG_threshold_reg <= rx_next[3:0];
                        CONFIG_gain_reg      <= rx_next[6:4];
                        CONFIG_invert_reg    <= rx_next[7];
                    end
                    7'h06: MIXED_rw_lo_reg <= rx_next[3:0];
                    default: ;
                endcase
            end
        end
    end

    //====================================================================
    // SPI Transmit Block (Mode 0: change MISO on falling SCLK)
    // Loads a fresh read_byte on the falling edge that starts each data
    // byte (bit_idx==0 with the command byte already consumed).
    //====================================================================

    always @(negedge sclk or posedge spi_arst) begin
        if (spi_arst) begin
            miso      <= 1'b0;
            tx_shift  <= 8'd0;
            tx_active <= 1'b0;
        end
        else if (!rw_bit && cmd_done && bit_idx == 3'd0) begin
            miso      <= read_byte[7];
            tx_shift  <= {read_byte[6:0], 1'b0};
            tx_active <= 1'b1;
        end
        else if (tx_active) begin
            miso     <= tx_shift[7];
            tx_shift <= {tx_shift[6:0], 1'b0};
        end
        else begin
            miso <= 1'b0;
        end
    end

    //====================================================================
    // Output Assignments
    //====================================================================

    assign CONTROL_enable_o   = CONTROL_enable_reg;
    assign CONTROL_mode_o     = CONTROL_mode_reg;
    assign CONTROL_reserved_o = CONTROL_reserved_reg;
    assign DATA_IN_data_o     = DATA_IN_data_reg;
    assign CONFIG_threshold_o = CONFIG_threshold_reg;
    assign CONFIG_gain_o      = CONFIG_gain_reg;
    assign CONFIG_invert_o    = CONFIG_invert_reg;
    assign MIXED_rw_lo_o      = MIXED_rw_lo_reg;

endmodule
